72	@RestController
73	@CrossOrigin(exposedHeaders = "errors, content-type")
74	@RequestMapping("/api")
75	public class OwnerRestControllerV1 implements OwnersApi {
76	
77	    /**
78	     * Dedicated audit logger. A single line is emitted here on each successful owner create,
79	     * carrying the new owner's id, customer code and registration date.
80	     */
81	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
82	
83	    /**
84	     * Maximum number of owners a single city may hold. A create whose city already contains this many
85	     * owners is rejected with a {@code 409 Conflict} (see {@link #rejectCityAtCapacity}).
86	     */
87	    private static final int MAX_OWNERS_PER_CITY = 50;
88	
89	    /**
90	     * Maximum number of owners that may be registered in a single day. A create made once this many
91	     * owners already carry today's {@code registrationDate} is rejected with a {@code 429 Too Many
92	     * Requests} (see {@link #rejectDailyRegistrationLimitReached}).
93	     */
94	    private static final int MAX_OWNERS_PER_DAY = 100;
95	
96	    /**
97	     * The number of owners that must already carry a given day's {@code registrationDate} before a
98	     * create made that day is flagged with {@code bulkSignupWarning}. Once more than this many owners
99	     * have already been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
100	     */
101	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
102	
103	    /**
104	     * Request header carrying the client-supplied idempotency key for a create. When a create repeats
105	     * with a key already seen, the originally created owner is returned with {@code 200 OK} instead of
106	     * creating a duplicate (see {@link #addOwner}).
107	     */
108	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
109	
110	    /**
111	     * Remembers, per seen {@code Idempotency-Key}, the id of the owner that create originally produced,
112	     * so a repeated create carrying the same key replays that owner rather than creating a duplicate.
113	     */
114	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
115	
116	    private final ClinicService clinicService;
117	
118	    private final OwnerMapper ownerMapper;
119	
120	    private final PetMapper petMapper;
121	
122	    private final VisitMapper visitMapper;
