124	    public OwnerRestControllerV1(ClinicService clinicService,
125	                                 OwnerMapper ownerMapper,
126	                                 PetMapper petMapper,
127	                                 VisitMapper visitMapper) {
128	        this.clinicService = clinicService;
129	        this.ownerMapper = ownerMapper;
130	        this.petMapper = petMapper;
131	        this.visitMapper = visitMapper;
132	    }
