159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
162	        String idempotencyKey = idempotencyKey();
163	        if (idempotencyKey != null) {
164	            Integer existingId = this.idempotentCreates.get(idempotencyKey);
165	            if (existingId != null) {
166	                Owner existing = this.clinicService.findOwnerById(existingId);
167	                if (existing != null) {
168	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
169	                }
170	            }
171	        }
172	        normalizeAddress(ownerFieldsDto);
173	        rejectBlankOwnerFields(ownerFieldsDto);
174	        rejectInvalidPostcode(ownerFieldsDto);
175	        normalizeTelephone(ownerFieldsDto);
176	        normalizeEmail(ownerFieldsDto);
177	        String householdId = householdIdFor(ownerFieldsDto);
178	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
179	        rejectDuplicateIdentity(ownerFieldsDto, householdId);
180	        rejectHouseholdDuplicate(householdId, sharesHousehold);
181	        rejectCityAtCapacity(ownerFieldsDto.getCity());
182	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
183	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate());
184	        long registeredThatDay = countRegisteredOn(registrationDate);
185	        rejectDailyRegistrationLimitReached(registrationDate, registeredThatDay);
186	        HttpHeaders headers = new HttpHeaders();
187	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
188	        owner.setRegistrationDate(registrationDate);
189	        owner.setHouseholdId(householdId);
190	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
191	        owner.setBulkSignupWarning(registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD);
192	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
193	        markPossibleDuplicate(owner, sharesHousehold);
194	        this.clinicService.saveOwner(owner);
195	        if (idempotencyKey != null) {
196	            this.idempotentCreates.put(idempotencyKey, owner.getId());
197	        }
198	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
199	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
200	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
201	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
202	        headers.setLocation(UriComponentsBuilder.newInstance()
203	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
204	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
210	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
211	        if (currentOwner == null) {
212	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
213	        }
214	        normalizeAddress(ownerFieldsDto);
215	        currentOwner.setAddress(addressFor(ownerFieldsDto));
216	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
217	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
218	        currentOwner.setCity(ownerFieldsDto.getCity());
219	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
220	        currentOwner.setLastName(ownerFieldsDto.getLastName());
221	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
222	        normalizeEmail(ownerFieldsDto);
223	        currentOwner.setEmail(ownerFieldsDto.getEmail());
224	        currentOwner.setHouseholdId(householdIdFor(ownerFieldsDto));
225	        this.clinicService.saveOwner(currentOwner);
226	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
227	    }
