260	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
261	    @Override
262	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
263	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
264	        if (currentOwner != null) {
265	            Pet currentPet = this.clinicService.findPetById(petId);
266	            if (currentPet != null) {
267	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
268	                currentPet.setName(petFieldsDto.getName());
269	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
270	                this.clinicService.savePet(currentPet);
271	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
272	            }
273	        }
274	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
275	    }
