293	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
294	    @Override
295	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
296	        Owner owner = this.clinicService.findOwnerById(ownerId);
297	        if (owner != null) {
298	            Pet pet = owner.getPet(petId);
299	            if (pet != null) {
300	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
